using Jotunn.Configs;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.Chaga;

/// <summary>
/// Chaga, the black, cracked canker that bursts from the bark of dead birch in the Mistlands, brewed into a bitter tea.
/// Model: generated by AssetSource/Tools/make_forage_models.py.
/// </summary>
public class Chaga : ForageableBase
{
    /// <summary>
    /// Prefab name of the chaga item.
    /// </summary>
    public const string PrefabName = "WhiteHiltChaga";

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Chaga";

    /// <inheritdoc/>
    protected override string Description => "A black, cracked lump cut from a dead birch, rust-orange inside. Brewed long, it makes a bitter tea that toughens the skin.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Coal";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "Pickable_Mushroom";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.Mistlands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed.
        Min = 1,
        Max = 1,
        ForcePlacement = true,
        GroupSizeMin = 1,
        GroupSizeMax = 1,
        GroupRadius = 2f,
        MinAltitude = 1f,
        MaxTilt = 20f,
        ScaleMin = 0.85f,
        ScaleMax = 1.15f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => null;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        ReplacePlantMesh(visualRoot, IsItem(visualRoot) ? "chagaitem" : "chaga", 0.75f);
    }
}
